import{_ as o,o as d,c,a0 as t}from"./chunks/framework.Bogozrur.js";const u=JSON.parse('{"title":"2026-07-15：C++ 跟学课堂 01–06","description":"","frontmatter":{},"headers":[],"relativePath":"blog/2026-07-15-cpp-lessons-01-06.md","filePath":"blog/2026-07-15-cpp-lessons-01-06.md"}'),a={name:"blog/2026-07-15-cpp-lessons-01-06.md"};function i(l,e,r,s,n,h){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="_2026-07-15-c-跟学课堂-01–06" tabindex="-1">2026-07-15：C++ 跟学课堂 01–06 <a class="header-anchor" href="#_2026-07-15-c-跟学课堂-01–06" aria-label="Permalink to &quot;2026-07-15：C++ 跟学课堂 01–06&quot;">​</a></h1><p>今天按桌面资料包里的 <code>11_跟学课堂</code> 往前推进，把第 01 课到第 06 课的 practice 都跑通了。每课都是 README + main + practice + test_practice，编译统一用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g++ -std=c++20 -Wall -Wextra -Werror</span></span></code></pre></div><p>测试通过的标志很朴素：<code>test_practice</code> 无输出、退出码 0。中途踩过几次 <code>-Werror</code> 和逻辑边界，反而比“一次写对”记得更牢。</p><h2 id="今天推进到哪里" tabindex="-1">今天推进到哪里 <a class="header-anchor" href="#今天推进到哪里" aria-label="Permalink to &quot;今天推进到哪里&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课</th><th>主题</th><th>状态</th></tr></thead><tbody><tr><td>01</td><td>基础语法与单文件编译</td><td>通过</td></tr><tr><td>02</td><td>类型、控制流与输入输出</td><td>通过</td></tr><tr><td>03</td><td>函数、作用域与参数传递</td><td>通过</td></tr><tr><td>04</td><td>vector、string 与数组思维</td><td>通过</td></tr><tr><td>05</td><td>指针、引用与生命周期</td><td>通过</td></tr><tr><td>06</td><td>结构体、类与封装</td><td>进行中（概念已过，practice 待收尾）</td></tr></tbody></table><p>资料包本身也从“目录很多”收成了可执行主线：跟学课堂是日常入口，MIT / GitHub 项目后置。</p><h2 id="各课真正留下的点" tabindex="-1">各课真正留下的点 <a class="header-anchor" href="#各课真正留下的点" aria-label="Permalink to &quot;各课真正留下的点&quot;">​</a></h2><h3 id="第-01-课-先能编译-再谈语法" tabindex="-1">第 01 课：先能编译，再谈语法 <a class="header-anchor" href="#第-01-课-先能编译-再谈语法" aria-label="Permalink to &quot;第 01 课：先能编译，再谈语法&quot;">​</a></h3><ul><li>程序从 <code>main</code> 开始；<code>-Wall -Wextra -Werror</code> 一开始就开。</li><li>空壳里的 <code>(void)x;</code> 只是消“未使用参数”警告，实现后要删掉。</li><li><code>1LL * n * (n + 1) / 2</code> 不是公式花活，是让乘法在 <code>long long</code> 里做，防 <code>int</code> 溢出。</li><li><code>assert</code> 在 <code>test_practice</code> 里：全对就安静，错了才叫。</li></ul><h3 id="第-02-课-类型陷阱和控制流" tabindex="-1">第 02 课：类型陷阱和控制流 <a class="header-anchor" href="#第-02-课-类型陷阱和控制流" aria-label="Permalink to &quot;第 02 课：类型陷阱和控制流&quot;">​</a></h3><ul><li>整数除法 <code>5/2 == 2</code>；要小数至少一侧是浮点，或 <code>static_cast&lt;double&gt;(a) / b</code>。</li><li><code>clamp</code>、<code>sign</code>、边界 <code>n &lt; 1</code> 这类题，逼着先想特殊输入。</li><li>偶数求和我用了 <code>k(k+2)/4</code> 的闭式；和 <code>m=n/2; m*(m+1)</code> 等价，一个更巧，一个更直。</li><li>第一次挂测试是因为 <code>count_digits</code> 算了 <code>dig</code> 却 <code>return 0</code>，警告也变成错误。</li></ul><h3 id="第-03-课-引用到底改的是谁" tabindex="-1">第 03 课：引用到底改的是谁 <a class="header-anchor" href="#第-03-课-引用到底改的是谁" aria-label="Permalink to &quot;第 03 课：引用到底改的是谁&quot;">​</a></h3><ul><li>值传递改副本；<code>int&amp;</code> 改调用方；<code>const T&amp;</code> 只读且少拷贝。</li><li><code>swap_int</code> 必须引用；<code>max_ref</code> 返回引用后，<code>r = 100</code> 会改到原来的变量。</li><li><code>mean</code> 返回 <code>double</code>：总和可以是整数，平均常常有小数，除法前要进浮点。</li><li><code>vector</code> 这节开始 downstream 用起来：<code>empty</code> / <code>size</code> / 范围 for。</li></ul><h3 id="第-04-课-下标、原地修改、第一次出现" tabindex="-1">第 04 课：下标、原地修改、第一次出现 <a class="header-anchor" href="#第-04-课-下标、原地修改、第一次出现" aria-label="Permalink to &quot;第 04 课：下标、原地修改、第一次出现&quot;">​</a></h3><ul><li><code>find_first</code> 第一次写成“最后一次”，因为循环里不断覆盖 <code>pos</code>；应找到就 <code>return i</code>。</li><li><code>to_upper_ascii</code> 必须用 <code>char&amp;</code> 才能改 string；只转 <code>a</code>–<code>z</code>。</li><li><code>int</code> 和 <code>size_t</code> 比较会触发 <code>-Werror=sign-compare</code>，用 <code>static_cast&lt;int&gt;(a.size())</code> 或 <code>size_t</code> 下标。</li><li><code>substr(pos)</code>：<code>pos == size()</code> 合法，得空串；<code>pos &gt; size()</code> 才异常。这和 <code>s[size()]</code> 不是一回事。</li></ul><h3 id="第-05-课-指针先问能不能碰" tabindex="-1">第 05 课：指针先问能不能碰 <a class="header-anchor" href="#第-05-课-指针先问能不能碰" aria-label="Permalink to &quot;第 05 课：指针先问能不能碰&quot;">​</a></h3><ul><li><code>&amp;x</code> 取址，<code>*p</code> 解引用，<code>nullptr</code> 表示空。</li><li><code>if (!a || !b) return;</code>：空指针当假值，解引用前先判断。</li><li><code>index_of</code> 返回 <code>&amp;a[i]</code>；返回的指针只在 vector 还活着、且没因扩容搬家前可靠。</li><li><code>strlen_c</code> 数到 <code>&#39;\\0&#39;</code>；<code>nullptr</code> 返回 0。参数指针按值传，函数里 <code>++s</code> 不改调用方。</li></ul><h3 id="第-06-课-封装和不变量" tabindex="-1">第 06 课：封装和不变量 <a class="header-anchor" href="#第-06-课-封装和不变量" aria-label="Permalink to &quot;第 06 课：封装和不变量&quot;">​</a></h3><ul><li><code>struct</code> / <code>class</code> 语言上主要差默认访问；风格上：纯数据聚合常用 struct，有规矩要守常用 class。</li><li><strong>不变量</strong>：对象合法时必须始终成立的规则，例如余额 <code>&gt;= 0</code>、分数分母 <code>!= 0</code>。靠 private + 构造/接口维护，不靠调用方自觉。</li><li><code>int manhattan() const</code> 里，后面的 <code>const</code> 表示<strong>不修改当前对象</strong>，和前面修饰返回值的 <code>const</code> 不是一回事。</li><li><code>int x{0}</code> 是花括号初始化；对 <code>int</code> 近似 <code>= 0</code>，但 <code>{}</code> 更防收窄（如 <code>int n{3.14}</code> 会直接编译失败）。</li></ul><h2 id="今天反复出现的编译-调试习惯" tabindex="-1">今天反复出现的编译/调试习惯 <a class="header-anchor" href="#今天反复出现的编译-调试习惯" aria-label="Permalink to &quot;今天反复出现的编译/调试习惯&quot;">​</a></h2><ol><li>PowerShell 路径用 <code>C:\\Users\\...</code>，不要用 Git Bash 的 <code>/c/Users/...</code>。</li><li>运行当前目录程序写 <code>.\\test_practice.exe</code>。</li><li><code>test_practice</code> 没输出通常是通过，不是没跑起来。</li><li><code>-Werror</code> 会把“赋值未使用”“有符号比较”直接打死，逼着写干净。</li></ol><h2 id="还没展开但记下坑位" tabindex="-1">还没展开但记下坑位 <a class="header-anchor" href="#还没展开但记下坑位" aria-label="Permalink to &quot;还没展开但记下坑位&quot;">​</a></h2><ul><li>迭代器：本阶段先会下标和范围 for；正式放到 STL 课再系统练 <code>begin</code>/<code>end</code>。</li><li>vector 扩容后旧指针/引用/迭代器可能失效：先记住规则，写代码时别攥着 <code>&amp;v[0]</code> 再疯狂 <code>push_back</code>。</li></ul><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>[ ] 收尾第 06 课 practice：<code>Point</code> / <code>BankAccount</code> / <code>distance_l1</code> / <code>RunningMax</code></li><li>[ ] 第 07 课：构造、析构与 RAII</li><li>[ ] 第 08 课：STL 容器与 algorithm，把容器选择重新接到刷题</li><li>[ ] 第 4 周末做词频 Top K，当作语言阶段验收</li></ul><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>今天不是在收藏语法名词，而是在把“能编译、能测、能解释自己写的每一行”练成默认动作。指针和封装都开始碰对象生命周期了，后面 RAII 会更顺。</p>',28)])])}const b=o(a,[["render",i]]);export{u as __pageData,b as default};
